+		return expiresNormal
+	}
+	delta := ts.Sub(now)
+	switch {
+	case delta <= 0:
+		return expiresExpired
+	case delta < 7*24*time.Hour:
+		return expiresSoon
+	default:
+		return expiresNormal
+	}
